export class RunStore {
  readonly config: ProjectsConfig
  private readonly projectsById = new Map<string, ProjectConfig>()
  private readonly options: Required<Omit<RunStoreOptions, 'warn'>> & Pick<RunStoreOptions, 'warn'>

