  version: z.enum(EXPORT_VERSIONS),
  run_id: id,
  base_commit: sha,
  created_at: timestamp,
  updated_at: timestamp,
  definition: storedDefinitionSchema,
  values: z.record(z.string(), z.unknown()),
  next: z.array(z.string()),
